/**
 * The rules of the variant, in one place. Both the in-app Rules panel and the README's
 * rules section are rendered from this array, so the two can't drift: the README block
 * between its `RULES:BEGIN`/`RULES:END` markers is generated by `rulesMarkdown()` and a
 * test fails if the file on disk no longer matches (see test/ui/rules-text.test.ts, which
 * also rewrites it when run with `UPDATE_README=1`).
 *
 * Inline markup is deliberately tiny — `**bold**`, `` `code` `` and `[text](url)` — because
 * both renderers have to understand it.
 */

export type RulesBlock =
  | { kind: 'heading'; text: string }
  | { kind: 'para'; text: string }
  | { kind: 'bullets'; items: string[] }
  | { kind: 'table'; head: string[]; rows: string[][] };

