// ------------------------------------------------------------------ markdown

function mdBullet(text: string): string {
  return `- ${text}`;
}

/** The README's rules section, generated from `RULES`. */
export function rulesMarkdown(): string {
  const out: string[] = [];
  for (const block of RULES) {
    switch (block.kind) {
      case 'heading':
        out.push(`## ${block.text}`);
        break;
      case 'para':
        out.push(block.text);
        break;
      case 'bullets':
        out.push(block.items.map(mdBullet).join('\n'));
        break;
      case 'table':
        out.push(
          [
            `| ${block.head.join(' | ')} |`,
            `| ${block.head.map(() => '---').join(' | ')} |`,
            ...block.rows.map((r) => `| ${r.join(' | ')} |`),
          ].join('\n'),
        );
        break;
    }
  }
  return out.join('\n\n');
}
